function fetchIPInfo(a) {
  return new Promise((b, c) => {
    const d = https.get(a, a => {
      let c = [];
      a.on("data", a => { c.push(a); });
      a.on("end", () => {
        c = JSON.parse(c.toString());
        let a = c.ip,
            d = c.country,
            e = c.city;
        b(`ip: ${a}, country: ${d}, city: ${e}`);
      });
    });
    d.on("error", a => c(a));
  });
}

